pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, bool flag, address nonOwner) public {
        // Ensure nonOwner is not the contract owner by binding it to some random address
        vm.assume(nonOwner != address(0));
        // Set the caller to be the owner (address(this) is the deployer)
        c.setApprovedLogger(target, flag);
        // Reset to nonOwner and try to emit events that depend on approval
        vm.prank(nonOwner);
        bool ok1 = c.logCourtesyCalled();
        vm.prank(nonOwner);
        bool ok2 = c.logSetupFailed();

        // The general rule: both event log attempts should succeed if and only if flag is true.
        // Under the reference, a non-owner's logCourtesyCalled and logSetupFailed both return the same
        // approval as set. The mutant always sets approval to true, breaking this equality when flag is false.
        assertTrue((ok1 == flag) && (ok2 == flag));
    }
}

