pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address logger, address observer, bool newStatus, bool observerInitStatus) public {
        vm.assume(caller != address(0));
        vm.assume(logger != address(0));
        vm.assume(observer != address(0));
        vm.assume(logger != observer);
        vm.assume(observer != caller);
        vm.assume(logger != caller);

        // Setup: make caller the contract owner and set initial status for observer
        // We must transfer ownership. The contract has no explicit ownership transfer; we assume the deployer is the owner in the constructor.
        // Since the deployer is this test contract, and onlyOwner checks msg.sender == _contractOwner,
        // we prank as the owner to call setApprovedLogger to set up the initial state.
        // We need to call it as the deployer to set initial approvedLoggers[observer].
        // Then we call it as the same owner to change logger.
        // The invariant: after the second call, observer's status must equal observerInitStatus, because observer is not the logger and not the caller.

        vm.prank(address(this));
        c.setApprovedLogger(observer, observerInitStatus);

        // Now call setApprovedLogger again as the owner with the fuzzed logger and newStatus
        vm.prank(address(this));
        c.setApprovedLogger(logger, newStatus);

        bool observerFinal = c.approvedLoggers(observer);
        assertTrue(observerFinal == observerInitStatus);
    }
}

