import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address requester, bytes32 digest, uint256 utxoSize, bytes memory redeemerOutputScript, uint256 requestedFee, bytes memory outpoint) public {
        vm.assume(caller != address(0));
        vm.prank(address(c));
        c.setApprovedLogger(caller, true);
        vm.prank(caller);
        bool result = c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint);
        assertTrue(result);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        bool obs = c.logGotRedemptionSignature(bytes32(0), bytes32(0), bytes32(0));
        assert(!c.approvedToLog(address(this)) ? !obs : true);
    }
}
